    "author": "",
    "description": "36氪获悉，2连板众泰汽车公告，公司目前正全力推进整车板块的复工复产，各项工作已取得阶段性进展，全新A0级车型已正式进入批量试制阶段。该车型主要面向海外市场，目标市场的法规认证、渠道建设及市场需求存在不确定性，截至目前尚未形成销售。同时公司目前仍面临一定的资金压力，后续量产及市场投放需要持续的资金投入，资金到位情况存在不确定性，可能影响车型的海外销售进度，请投资者理性投资，注意风险。",
    "content": "36氪获悉，2连板众泰汽车公告，公司目前正全力推进整车板块的复工复产，各项工作已取得阶段性进展，全新A0级车型已正式进入批量试制阶段。该车型主要面向海外市场，目标市场的法规认证、渠道建设及市场需求存在不确定性，截至目前尚未形成销售。同时公司目前仍面临一定的资金压力，后续量产及市场投放需要持续的资金投入，资金到位情况存在不确定性，可能影响车型的海外销售进度，请投资者理性投资，注意风险。"
