    "content": "中新社上海9月9日电 (记者 姜煜)2011年诺贝尔经济学奖得主、纽约大学教授托马斯·萨金特(Thomas Sargent)9日在上海举办的2026 Inclusion·外滩大会见解论坛上表示，如今AI(人工智能)快速进步的背后有两个重要条件：海量数据和强大算力，而中国在大数据应用方面是引领者之一，不仅体现在社会科学，也体现在物理学等基础研究领域。"
