    "content": "怎么来的 ：做关键词调研时发现的需求。搜 \"album cover size\"、\"distrokid album art size\" 这类词的人意图很具体——想做适配歌曲的封面，所以有了这个产品。 给谁用 ：用 Suno / Udio 做歌的，和自己写歌录歌的。歌做完要发到 Spotify / Apple Music ，走 DistroKid 、TuneCore 、CD Baby ，封面绕不过去：尺寸、色彩空间、文件大小、不能带网址和社交账号、显式内容要不要贴 Parental Advisory ，各家规则还不一样…"
