    "content": "从第二十六届中国国际投资贸易洽谈会获悉，近日，商务部新增84个全国重点外资项目，总投资额194.6亿美元。据了解，新增项目主要集中在制造业，涉及机电装备、化工能源、汽车、医疗健康等领域。（央视新闻）"
