    "description": "36氪获悉，安井食品公告，公司拟通过全资子公司香港安井与Mutual Strategy Limited（简称“合作方”）签署股东协议，共同在香港设立路径公司。香港路径公司设立后，将分别在印度尼西亚设立印尼生产子公司及印尼贸易子公司。香港安井与合作方承诺按照各自50.5%和49.5%的持股比例，向香港路径公司以现金形式出资合计不少于7425万美元。按最低出资金额计算，香港安井出资3749.625万美元，合作方出资3675.375万美元。",
