    "description": "今年是叶兆言写作的第46年。1980年代初，他以先锋小说进入文坛，此后，他写小说、散文、随笔、非虚构，写南京，写民国，写知识分子，也写身边那些并不显眼的普通人。新时期文学的潮水一轮轮涨落，他一直站在浪潮里。 今年8月，他同时推出新书《一叶知百年》和《岭南十三讲》。一本向外，从晚清写到当代，以百位人物串起五代知识分子的命运；一本向内回看自己怎样成为一个作家，这是他第一次系统谈论自己的文学经验。值这两本书出版，9月7日，一场创作研讨会举办。…",
    "content": "今年是叶兆言写作的第46年。1980年代初，他以先锋小说进入文坛，此后，他写小说、散文、随笔、非虚构，写南京，写民国，写知识分子，也写身边那些并不显眼的普通人。新时期文学的潮水一轮轮涨落，他一直站在浪潮里。 今年8月，他同时推出新书《一叶知百年》和《岭南十三讲》。一本向外，从晚清写到当代，以百位人物串起五代知识分子的命运；一本向内回看自己怎样成为一个作家，这是他第一次系统谈论自己的文学经验。值这两本书出版，9月7日，一场创作研讨会举办。 谈到自己为什么还在写，叶兆言提到前段时间宣布退役的拉塞尔，他有些伤感，NBA已…"
