    "description": "9月8日，山东济南。46岁张云峰以大一新生的身份到山东中医药大学报到。他说自己17岁时被同济大学建筑工程专业录取，毕业后从事和房地产相关的工作，如今人到中年更关注自己与家人的健康，于是三年前辞职备考，今年第三次参加高考取得542分的成绩被录取，未来想学习中医知识帮助身边的人。",
