    "content": "美国白宫8日发布公告说，美国总统特朗普当天签署文件，依据《斯穆特-霍利关税法》第338条款，禁止部分加拿大酒精饮料、摩托车、乳制品等商品进入美国市场，并对更多加拿大商品加征关税。 特朗普在公告中说，美国7月20日宣布对加拿大部分商品加征50%关税以来，加拿大政府维持对美国酒精饮料、乳制品和汽车的歧视做法并公布额外报复措施。因此，美国将从9月29日起禁止进口部分加拿大酒精饮料、乳制品和摩托车等商品。 此外，美国将从9月15日起对动物皮毛、芝士、家具、贱金属产品、铝合金产品等约100个品类的加拿大产品加征50%关税，同…"
