    "content": "新华社天津9月9日电（记者周润健）土家族八勾纹锦、壮族龙凤虎纹锦、侗族鱼鸟动物纹锦……9日，“指间经纬——中国妇女儿童博物馆藏南方少数民族织锦展”在天津博物馆启幕，9个少数民族的85件（套）现代织锦珍品集中亮相，吸引不少观众的目光。 9月9日，观众在参观展览。新华社记者 周润健 摄 织锦是以两组及以上染色丝线交织而成的多重组织提花丝织物，织造工序繁复，技艺门槛高。我国织锦技艺源远流长，周代的丝织物中就已出现织锦。根据显花方式不同，织锦又分为经锦和纬锦。 在我国南方地区，各少数民族世代传承织造技艺，巧手织就各具特色的…"
