    "content": "一沙一世界。 奥尔加·托卡尔丘克 波兰作家奥尔加·托卡尔丘克获得了2018年度的诺贝尔文学奖。在受奖演讲中，她提到一种无法掩盖又难以形容的感觉：“这个世界出了问题。这种感觉曾经只属于神经质的诗人，如今却已成为人群中普遍存在的一种不确定性和焦虑感。”她的短篇小说《万圣山》，恰好描述了一个出问题的世界——那就是我们所处的这个世界。 《万圣山》弥漫着诡异、清冷又颓败的氛围，令人不安。故事的主角“我”是一位心理学家，因发明了能预测儿童和青少年个人发展趋势的心理学测试而闻名学界。故事开始时，“我”已步入晚年，身患癌症，被医生…"
