    "description": "9月9日至9月13日来服贸会，走进教育服务专题展区，沉浸式、互动式体验AI教育新场景，近距离感受科技赋能教育新生态。 据介绍，教育服务专题展区的展览规模约3300平方米。专题紧扣“教育强国，智创未来”主题，打造“高质量教育服务国际合作”“智慧教育赋能”两大核心展区。 推出“京娃”系列智能体、助力区域协同发展的“教育新地图”，首发教育大模型、教育机器人等多款前沿科创产品。 记者：马晓冬 新华社音视频部制作",
    "content": "9月9日至9月13日来服贸会，走进教育服务专题展区，沉浸式、互动式体验AI教育新场景，近距离感受科技赋能教育新生态。 据介绍，教育服务专题展区的展览规模约3300平方米。专题紧扣“教育强国，智创未来”主题，打造“高质量教育服务国际合作”“智慧教育赋能”两大核心展区。 推出“京娃”系列智能体、助力区域协同发展的“教育新地图”，首发教育大模型、教育机器人等多款前沿科创产品。 记者：马晓冬 新华社音视频部制作"
