    "content": "新华社科威特城9月9日电（记者尹炣）萨那消息：也门胡塞武装9日称，沙特阿拉伯战机在过去数小时内对也门4个省发动了32次空袭。 据胡塞武装控制的马西拉电视台当天报道，过去数小时内，沙特战机对马里卜省、焦夫省、塔伊兹省和荷台达省多地发动了32次空袭。报道未说明具体袭击目标以及人员伤亡或财产损失情况。 沙特方面尚未对此作出回应。 一名也门政府军军方人士当天向新华社记者表示，沙特此次空袭目标为胡塞武装控制地区，旨在为政府军提供空中支援。目前，胡塞武装与政府军的地面战斗仍在持续。 沙特方面8日表示，胡塞武装袭击了沙特多地民用…"
