    "content": "新华社广州9月9日电（记者樊曦）记者从中铁十六局集团有限公司获悉，一座覆盖面积达2.2万平方米的超大气膜在广州白云展览中心项目正式投入使用，将最大开挖深度为16.65米的基坑施工区域整体覆盖，有效降低施工扬尘、噪声及恶劣天气对工程建设的影响。 白云展览中心项目由广州白云产业投资集团有限公司投资建设，总建筑面积约12.96万平方米，规划建设会展场馆、商务办公楼、配套酒店及地下三层设施。项目施工现场邻近城市快速路、白云山风景名胜区及商住区，人流、车流较为密集。同时，广州雨季较长，台风、高温等天气也容易对露天施工作业造成…"
