    "description": "海关总署9月8日发布数据显示，今年前8个月，我国货物贸易进出口总值34.78万亿元，同比增速上行至17.6%，延续两位数快速增长态势。其中，8月当月，我国进出口4.65万亿元，同比增长19.8%，出口、进口分别增长18.6%、21.7%，进口月度同比增速连续6个月超过出口。 8月25日，集装箱货轮停靠在山东港口青岛港前湾集装箱码头（无人机照片）。新华社发（张进刚摄） 对于我国外贸的表现，海关总署统计分析司司长吕大良表示，复杂多变的外部环…",
    "content": "海关总署9月8日发布数据显示，今年前8个月，我国货物贸易进出口总值34.78万亿元，同比增速上行至17.6%，延续两位数快速增长态势。其中，8月当月，我国进出口4.65万亿元，同比增长19.8%，出口、进口分别增长18.6%、21.7%，进口月度同比增速连续6个月超过出口。 8月25日，集装箱货轮停靠在山东港口青岛港前湾集装箱码头（无人机照片）。新华社发（张进刚摄） 对于我国外贸的表现，海关总署统计分析司司长吕大良表示，复杂多变的外部环境下，我国货物贸易增势稳定充分体现了完整产业体系对外贸的坚韧支撑，以及科技创新能…"
