    "content": "讲述中央文库一号机密往事的电影《密档》正在热映，电影用一种轻巧而生活的视角讲述了厚重的历史往事，各色人物粉墨登场又隐入尘烟，弄堂街坊里有人运筹帷幄，有人你侬我侬，乱世里众生百态如浮萍，身不由己的飘摇中又有各自鲜活的色彩。 很多人会觉得电影里那个房东有点眼熟，银幕上那个穿着墨绿色天鹅绒睡袍、脚踩皮拖鞋、手里捧着紫砂壶的上海房东，懒洋洋地生活在弄堂深处。他有一点讲究，有一点圆滑，有一点事不关己，却又在乱世里保留着普通人的善意。 《密档》人物海报 扮演房东顾少棠的演员是邵峰。在上世纪90年代到千禧年前后，他是内地古装剧里…"
