    "author": "jiames1969",
    "description": "最近在整理多语言项目时，我经常遇到一个看似简单、实际很容易出错的问题：翻译内容可以生成，但 JSON 的 key 、嵌套路径和项目目录结构不能被破坏。 JsonTranslate 是一个面向开发者、产品团队和本地化团队的浏览器端工具，重点是让结构化文件翻译更适合进入日常开发流程。 它支持上传、拖拽或粘贴 JSON 、Markdown 、TXT 等文件，也可以处理完整项目。翻译时保留 JSON key 、嵌套路径和目录结构； Git di…",
    "content": "最近在整理多语言项目时，我经常遇到一个看似简单、实际很容易出错的问题：翻译内容可以生成，但 JSON 的 key 、嵌套路径和项目目录结构不能被破坏。 JsonTranslate 是一个面向开发者、产品团队和本地化团队的浏览器端工具，重点是让结构化文件翻译更适合进入日常开发流程。 它支持上传、拖拽或粘贴 JSON 、Markdown 、TXT 等文件，也可以处理完整项目。翻译时保留 JSON key 、嵌套路径和目录结构； Git diff 风格的变更检测则适合只处理新增或修改过的内容，减少重复翻译。 对于已有 i…"
