    "content": "新华社南昌9月9日电（记者胡喆、陈毓珊）记者9月9日从中国科学院获悉，全球首套连续塔式萃取分离特色锂矿石伴生铷铯资源示范线在江西全面稳定达产。这套由中国科学院过程工程研究所联合赣锋锂业合作打造的生产线，把藏在锂矿石里的稀有金属铷、铯高效提取出来，产出纯度99.9%以上的碳酸铷、碳酸铯，产品已经投放市场销售，标志着我国在稀有金属绿色分离技术上实现重要突破。 铷和铯是航空航天、精密仪器等尖端产业离不开的稀有金属。据介绍，我国缺少可以直接开采的铯榴石矿，铷、铯大多“藏”在锂矿石、盐湖卤水当中，属于低品位伴生资源。过去想要…"
