    "content": "新华社北京9月9日电（记者冀泽、王承昊）《中共中央 国务院关于支持福建探索海峡两岸融合发展新路 建设两岸融合发展示范区的意见》发布实施将满3周年。国务院台办发言人陈斌华9日在例行新闻发布会上答问表示，示范区建设取得阶段性进展，台胞台企登陆第一家园更加便利，闽台经济交流合作持续热络，福建全域融合发展保持良好势头，闽台人文社会交流不断深化。 陈斌华介绍，3年来，中央和国家机关有关部门制定出台了一系列配套政策文件，福建先后发布5批74项促进闽台融合政策措施，组织实施206个闽台融合发展重点项目，总投资超1.3万亿元。今年…"
